// TypeScript Version: 4.1

/// <reference types="@stdlib/types"/>

/**
* Status code.
*
* ## Notes
*
* -   If the operation was successful, the function returns a status code equal to `0`; otherwise, the function returns a status code equal to `-i`, corresponding to the `i`-th argument which had an illegal value.
*/
type StatusCode = number;

/**
* Interface describing `dlasrt`.
*/
interface Routine {
	/**
	* Sorts a double-precision floating-point strided array in increasing or decreasing order using quicksort, with insertion sort for small partitions (size <= 20).
	*
	* ## Notes
	*
	* -   If the operation was successful, the function returns a status code equal to `0`; otherwise, the function returns a status code equal to `-i`, corresponding to the `i`-th argument which had an illegal value.
	*
	* @param sortOrder - sort direction
	* @param N - number of elements to sort
	* @param D - array to sort in-place
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var D = new Float64Array( [ 5.0, 7.0, 9.0, 3.0, 11.0 ] );
	*
	* dlasrt( 'increasing', 5, D );
	* // D => <Float64Array>[ 3, 5, 7, 9, 11 ]
	*/
	( sortOrder: string, N: number, D: Float64Array ): StatusCode;

	/**
	* Sort a double-precision floating-point strided array in increasing or decreasing order using quicksort, with insertion sort for small partitions (size <= 20) and using alternative indexing semantics.
	*
	* ## Notes
	*
	* -   If the operation was successful, the function returns a status code equal to `0`; otherwise, the function returns a status code equal to `-i`, corresponding to the `i`-th argument which had an illegal value.
	*
	* @param sortOrder - sort direction
	* @param N - number of elements to sort
	* @param D - array to sort in-place
	* @param strideD - stride length for `D`
	* @param offsetD - starting index for `D`
	* @param stack - stack array
	* @param strideStack - stride length for `stack`
	* @param offsetStack - starting index for `stack`
	* @returns status code
	*
	* @example
	* var Float64Array = require( '@stdlib/array/float64' );
	*
	* var D = new Float64Array( [ 5.0, 7.0, 9.0, 3.0, 11.0 ] );
	* var stack = new Float64Array( 64 );
	*
	* dlasrt( 'increasing', 5, D, 1, 0, stack, 1, 0 );
	* // D => <Float64Array>[ 3.0, 5.0, 7.0, 9.0, 11.0 ]
	*/
	ndarray( sortOrder: string, N: number, D: Float64Array, strideD: number, offsetD: number, Stack: Float64Array, strideStack: number, offsetStack: number ): StatusCode;
}

/**
* LAPACK routine to sort a double-precision floating-point strided array in increasing or decreasing order using quicksort, with insertion sort for small partitions (size <= 20).
*
* ## Notes
*
* -   If the operation was successful, the function returns a status code equal to `0`; otherwise, the function returns a status code equal to `-i`, corresponding to the `i`-th argument which had an illegal value.
*
* @param sortOrder - sort direction: 'increasing' or 'decreasing'
* @param N - number of elements to sort
* @param D - array to sort in-place
* @returns status code
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
 * var D = new Float64Array( [ 5.0, 7.0, 9.0, 3.0, 11.0 ] );
 *
 * dlasrt( 'increasing', 5, D );
 * // D => <Float64Array>[ 3.0, 5.0, 7.0, 9.0, 11.0 ]
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
 * var D = new Float64Array( [ 5.0, 7.0, 9.0, 3.0, 11.0 ] );
 * var stack = new Float64Array( 64 );
 *
 * dlasrt( 'increasing', 5, D, 1, 0, stack, 1, 0 );
 * // D => <Float64Array>[ 3.0, 5.0, 7.0, 9.0, 11.0 ]
*/
declare var dlasrt: Routine;


// EXPORTS //

export = dlasrt;
